// -------------------------------------------------------------
// Helpers
// -------------------------------------------------------------

func validAction(a string) bool {
	switch strings.ToLower(strings.TrimSpace(a)) {
	case "timeout", "kick", "ban", "warn", "lockdown":
		return true
	default:
		return false
	}
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}
